{
  "title": "Conversation Telemetry",
  "css": "* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1e293b;
  background: #f8fafc;
  padding: 16px;
}
.panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 10px;
}
.header h2 {
  font-size: 1.1rem;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.01em;
}
.header .badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  background: #e2e8f0;
  border-radius: 9999px;
  color: #475569;
}
.section-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #64748b;
  margin-bottom: 8px;
}
.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}
.stat-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.stat-label {
  font-size: 0.75rem;
  color: #64748b;
  display: flex;
  align-items: center;
  gap: 6px;
}
.stat-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
.stat-dot.user { background: #3b82f6; }
.stat-dot.assistant { background: #10b981; }
.stat-dot.system { background: #8b5cf6; }
.stat-dot.tool { background: #f59e0b; }
.stat-val {
  font-size: 1.35rem;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.2;
}
.highlight-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 12px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}
.highlight-card .info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.highlight-card .main-stat {
  font-size: 1.5rem;
  font-weight: 800;
  color: #0f172a;
}
.highlight-card .sub {
  font-size: 0.75rem;
  color: #64748b;
}
.tool-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 8px;
}
.tool-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  background: #f1f5f9;
  border-radius: 6px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.75rem;
  color: #334155;
}
.tool-index {
  font-size: 0.65rem;
  font-weight: 700;
  color: #94a3b8;
  width: 16px;
}
.tool-name {
  font-weight: 600;
  color: #0f172a;
  word-break: break-all;
}
.empty-state {
  font-size: 0.8rem;
  color: #94a3b8;
  font-style: italic;
  padding: 8px 4px;
