  "body": "<div class="panel">
  <div class="header">
    <h2>Conversation Stats</h2>
    <span id="total-badge" class="badge">0 messages</span>
  </div>

  <div>
    <div class="section-title">Messages by Role</div>
    <div class="card-grid">
      <div class="stat-card">
        <div class="stat-label"><span class="stat-dot user"></span>User</div>
        <div id="count-user" class="stat-val">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label"><span class="stat-dot assistant"></span>Assistant</div>
        <div id="count-assistant" class="stat-val">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label"><span class="stat-dot system"></span>System</div>
        <div id="count-system" class="stat-val">0</div>
      </div>
      <div class="stat-card">
        <div class="stat-label"><span class="stat-dot tool"></span>Tool</div>
        <div id="count-tool" class="stat-val">0</div>
      </div>
    </div>
  </div>

  <div>
    <div class="section-title">Longest Message</div>
    <div class="highlight-card">
      <div class="info">
        <div id="longest-length" class="main-stat">0 chars</div>
        <div id="longest-role" class="sub">Role: -</div>
      </div>
    </div>
  </div>

  <div>
    <div class="section-title">Recent Tool Calls (last 5)</div>
    <div id="tool-list" class="tool-list">
      <div class="empty-state">None recorded</div>
    </div>
  </div>
</div>",
  "scripts": [
    "const updatePanel = () => {
  const messages = ml?.current?.messages || [];

  const roleCounts = {
    user: 0,
    assistant: 0,
    system: 0,
    tool: 0
  };

  let longestCharCount = 0;
  let longestMessageRole = '-';
  const toolCalls = [];

  messages.forEach((msg) => {
    const role = msg?.role || 'unknown';
    if (roleCounts[role] !== undefined) {
      roleCounts[role] = roleCounts[role] + 1;
    } else {
      roleCounts[role] = 1;
    }

    const content = msg?.content || '';
    const len = content.length;
    if (len > longestCharCount) {
      longestCharCount = len;
      longestMessageRole = role;
    }

    const tcs = msg?.tool_calls;
    if (tcs && Array.isArray(tcs)) {
      tcs.forEach((tc) => {
        const name = tc?.function?.name || 'unknown_tool';
        toolCalls.push(name);
      });
    }
  });

  const totalMsgEl = root.querySelector('#total-badge');
  if (totalMsgEl) {
    totalMsgEl.textContent = `${messages.length} message${messages.length === 1 ? '' : 's'}`;
  }

  const userEl = root.querySelector('#count-user');
  if (userEl) userEl.textContent = `${roleCounts.user}`;

  const assistantEl = root.querySelector('#count-assistant');
  if (assistantEl) assistantEl.textContent = `${roleCounts.assistant}`;

  const systemEl = root.querySelector('#count-system');
  if (systemEl) systemEl.textContent = `${roleCounts.system}`;

  const toolEl = root.querySelector('#count-tool');
  if (toolEl) toolEl.textContent = `${roleCounts.tool}`;

  const longestLenEl = root.querySelector('#longest-length');
  if (longestLenEl) {
    longestLenEl.textContent = `${longestCharCount.toLocaleString()} chars`;
  }

  const longestRoleEl = root.querySelector('#longest-role');
  if (longestRoleEl) {
    longestRoleEl.textContent = longestCharCount > 0 ? `Sent by: ${longestMessageRole}` : 'Role: -';
  }

  const toolListEl = root.querySelector('#tool-list');
  if (toolListEl) {
    toolListEl.replaceChildren();
    const recentFive = toolCalls.slice(-5).reverse();

    if (recentFive.length === 0) {
      const emptyEl = root.create('div');
      emptyEl.classList.add('empty-state');
      emptyEl.textContent = 'None recorded';
      toolListEl.append(emptyEl);
    } else {
      recentFive.forEach((toolName, idx) => {
        const item = root.create('div');
        item.classList.add('tool-item');

        const num = root.create('span');
        num.classList.add('tool-index');
        num.textContent = `#${idx + 1}`;

        const nameSpan = root.create('span');
        nameSpan.classList.add('tool-name');
        nameSpan.textContent = toolName;

        item.append(num);
        item.append(nameSpan);
        toolListEl.append(item);
      });
    }
  }
};

updatePanel();"
  ]
}
